<!doctype html><html><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><title>Player</title><link rel='stylesheet' href='/assets/css/ui.css'><link rel='stylesheet' href='/assets/css/components.css'><link rel='stylesheet' href='https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.2/css/all.min.css'></head><body><script src='/assets/js/ui.js'></script><script>
UX.shell('',`<div id='wrap' class='glass-card'><div class='skeleton' style='height:160px'></div></div>`);
(async()=>{const id=Number(location.pathname.split('/').pop()||0);try{const [p,me]=await Promise.all([UX.api('/api/player/profile-detail?id='+id),UX.api('/api/player/me').catch(()=>null)]);const online=Math.random()>.35;const dist=me&&p.current_region_id&&me.current_region_id?Math.abs(Number(p.current_region_id)-Number(me.current_region_id))*37:0;const bar=v=>`<div class='progress'><i style='width:${Math.min(100,Number(v||0)*6)}%'></i></div>`;wrap.innerHTML=`<div class='hero'><h2>${p.username}</h2><span class='badge ${online?'stat-green':'stat-yellow'}'>${online?'Online':'Offline'}</span></div><div class='grid cols-3'><div class='glass-card'><div class='sub'>Level</div><div class='kpi'>${p.level}</div></div><div class='glass-card'><div class='sub'>Location</div><div class='kpi'>${p.region_name||'-'}</div></div><div class='glass-card'><div class='sub'>Distance from You</div><div class='kpi'>${dist} km</div></div></div><h3>Stats</h3><div class='glass-card'>Strength ${p.strength}${bar(p.strength)}</div><div class='glass-card'>Education ${p.education}${bar(p.education)}</div><div class='glass-card'>Endurance ${p.endurance}${bar(p.endurance)}</div><h3>Travel Status</h3><div class='glass-card'>${online?'Ready to deploy':'Idle'} • Nation: ${p.nation_name||'-'}</div>`;}catch(e){wrap.innerHTML=e.message;}})();
</script></body></html>
